SELECT id
FROM kb_embedding_job
WHERE tenant_id = #{tenantId}
  AND id = #{jobId}
  AND status IN ('PARSING', 'INDEXING')
  AND lease_owner = #{leaseOwner}
  AND lease_token = #{leaseToken}
  AND version = #{fenceVersion}
  AND lease_until > #{now}
  AND deleted_at IS NULL
FOR UPDATE

mapper.update:
UPDATE kb_embedding_job
SET lease_until = #{leaseUntil},
    updated_at = #{now}
WHERE tenant_id = #{tenantId}
  AND id = #{jobId}
  AND status IN ('PARSING', 'INDEXING')
  AND lease_owner = #{leaseOwner}
  AND lease_token = #{leaseToken}
  AND version = #{fenceVersion}
  AND lease_until > #{now}
  AND #{leaseUntil} > #{now}
  AND deleted_at IS NULL

UPDATE kb_embedding_job
SET status = 'COMPLETED',
    next_retry_at = NULL,
    failure_code = NULL,
    failure_reason = NULL,
    lease_owner = NULL,
    lease_token = NULL,
    lease_until = NULL,
    updated_at = #{now},
    version = version + 1
WHERE tenant_id = #{tenantId}
  AND id = #{jobId}
  AND status IN ('PARSING', 'INDEXING')
  AND lease_owner = #{leaseOwner}
  AND lease_token = #{leaseToken}
  AND version = #{fenceVersion}
  AND lease_until > #{now}
  AND deleted_at IS NULL

UPDATE kb_embedding_job
SET status = 'RETRY_WAIT',
    next_retry_at = #{nextRetryAt},
    failure_code = #{failureCode},
    failure_reason = #{failureSummary},
    lease_owner = NULL,
    lease_token = NULL,
    lease_until = NULL,
    updated_at = #{now},
    version = version + 1
WHERE tenant_id = #{tenantId}
  AND id = #{jobId}
  AND status IN ('PARSING', 'INDEXING')
  AND lease_owner = #{leaseOwner}
  AND lease_token = #{leaseToken}
  AND version = #{fenceVersion}
  AND lease_until > #{now}
  AND deleted_at IS NULL

UPDATE kb_embedding_job
SET status = 'FAILED',
    next_retry_at = NULL,
    failure_code = #{failureCode},
    failure_reason = #{failureSummary},
    lease_owner = NULL,
    lease_token = NULL,
    lease_until = NULL,
    updated_at = #{now},
    version = version + 1
WHERE tenant_id = #{tenantId}
  AND id = #{jobId}
  AND status IN ('PARSING', 'INDEXING')
  AND lease_owner = #{leaseOwner}
  AND lease_token = #{leaseToken}
  AND version = #{fenceVersion}
  AND lease_until > #{now}
  AND deleted_at IS NULL
